self.KB_CONTENT["card:757719"]={"id":"card:757719","ty":"card","sourceId":"757719","title":"『採購變更單建立作業』中的『採購金額 (TF012)』為何？","ver":"iGP","topic":"採購單","keywords":["採購單","變更單","單價","大於"],"y":"other","answer":"* 此欄位必須大於等於零。* 採購金額=採購加總後數量×採購單價。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
