self.KB_CONTENT["card:783813"]={"id":"card:783813","ty":"card","sourceId":"783813","title":"『資產異動統計表』中的『選擇日期』為何？","ver":"GP4以上","topic":"統計表","keywords":["統計表","資產","異動","期間"],"y":"other","answer":"* 可點選(icon)或[F2]日期快手查詢，需列印起始日期之期間。若空白表全部日期皆納入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
