self.KB_CONTENT["card:783093"]={"id":"card:783093","ty":"card","sourceId":"783093","title":"『票據單據性質清單』的作業重點有哪些？","ver":"GP4以上","topic":"單別","keywords":["單別","票據","款單","編號"],"y":"explain","answer":"■作業重點1.本報表資料列印依單別排序印出。2.單據性質：81.存款單據、82.提款單據、83.融資託票、84.融資借款、85.融資還款、86.抵押借款及87.抵押還款。3.編碼方式：1.日編、2.月編、3.流水號及4.手動編號。4.若編碼方式不等於「手動編號」時，則依編碼方式、年碼數及流水號碼數，顯示出編碼格式。EX.YYMMDD999YYMM99999，999999999YYYYMMDD999 (西元年四碼)YYYMMDD9999 (民國年三碼)否則，顯示空白。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
