self.KB_CONTENT["field:792998"]={"id":"field:792998","ty":"field","sourceId":"792998","title":"幣別","ver":"GP4以上","topic":"","keywords":[],"job":"每月製令變更狀況維護作業","code":"TH042","answer":"* 為託外加工時所使用的交易幣別。* 此欄位僅作顯示。","file":"fields.jsonl"};
