self.KB_CONTENT["error:876036"]={"id":"error:876036","ty":"error","sourceId":"876036","title":"作業程式檔案不存在","ver":"AiGP1.1 以上","topic":"","job":"","cause":"","solution":"[*銷貨單憑證]]作業程式檔案不存在，可從主機或其他可開啟個案程式的電腦，複製c_modi、s_modi中的程式到本機。 或是在本機執行DsUpdate，以主機為來源做更新即可。","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:817428"]={"id":"error:817428","ty":"error","sourceId":"817428","title":"序號 000X 里程碑項下沒有設定對應的預算控管序號","ver":"GP4.0.21.0以上","topic":"","job":"","cause":"","solution":"里程碑代號+預算控管序號需存在於『預算控管建立作業』單身","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:889650"]={"id":"error:889650","ty":"error","sourceId":"889650","title":"沒有任何符合的資料","ver":"GP4.0.12.0以上","topic":"","job":"使用者系統別權限產生作業","cause":"","solution":"請在『群組資料建立作業』確認群組代號是否不存在，如果群組代號不存在，可以透過新增方式加入新的群組代號。","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:817334"]={"id":"error:817334","ty":"error","sourceId":"817334","title":"呼叫服務有問題:呼叫OAP服務解析資料有問題:Can not found Companyld(公司代號) in DSCMB","ver":"AIGP","topic":"","job":"生單助理","cause":"","solution":"點選ERP主畫面【數智員工】(娜娜圖示)→【生單助理】→【設計器】→【產品服務】→【服務URL內容】設定IP是否正確，需為ERPDB主機","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:817262"]={"id":"error:817262","ty":"error","sourceId":"817262","title":"您的權限不足，無法回答您的問題，抱歉!!!","ver":"AIGP","topic":"","job":"文件總結助手","cause":"","solution":"目前上傳未控卡，因建議專人統一上傳，但會檢視對談的帳號是否有附件權限，如無權限則出現\"您的權限不足，無法回答您的問題，抱歉!!!\"","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:852078"]={"id":"error:852078","ty":"error","sourceId":"852078","title":"無法起始化(連線失敗)","ver":"GP4.0.15.0以上","topic":"","job":"","cause":"","solution":"連線失敗需將整個ERP關閉後重啟後再進行操作即可。","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:811596"]={"id":"error:811596","ty":"error","sourceId":"811596","title":"無法產生憑證圖檔 ERROR MSG:沒找到DLL檔案","ver":"GP4.0.23.0以上","topic":"","job":"","cause":"","solution":"送簽到EF出現\"無法產生憑證圖檔 ERROR MSG:沒找到DLL檔案\"，該狀況是使用者電腦有安裝新程式，不過執行電子表單派班中心的主機並未安裝該程式，需將個案程式複製到主機並重新送簽即可","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:849485"]={"id":"error:849485","ty":"error","sourceId":"849485","title":"該年期或會計關帳年期之會計期間未設定!","ver":"GP4以上","topic":"","job":"","cause":"","solution":"請檢查『會計期間設定作業-ACTI07』是否有設定【關帳年月】【現行年月】之會計期間資料。 例如：【關帳年月】為202510，【現行年月】為202602，則2025年及2026年之期別均需設定。","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:821227"]={"id":"error:821227","ty":"error","sourceId":"821227","title":"銀行行號帳號不可空白","ver":"GP40.iGP以上","topic":"","job":"","cause":"","solution":"可確認該單別於『單據性質設定作業-NOTI06』是否有勾選【FEDI】，如有勾【FEDI】表示後續會透過『轉帳媒體產生作業』產生媒體檔將匯款資料上傳到網路銀行，所以會強制要求需輸入銀行帳號。 如確定不輸入銀行帳號，且無媒體檔轉檔議題，可將此勾選拿掉，或者是另外新增一個單別，此單別不勾選【FEDI】，後續如有此種單據需輸入則使用未勾選FEDI的單別進行登打。","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:849715"]={"id":"error:849715","ty":"error","sourceId":"849715","title":"請先註冊 C_Disbin\\WMFPrinter.exe 後才可正常列印","ver":"IGP 以上","topic":"","job":"","cause":"","solution":"若列印時會出現「請先註冊 C_Disbin\\WMFPrinter.exe 後才可正常列印」，請至SmartERP/C_DWMFPrinter.exe，右鍵點選\"以系統管理員身分執行\"，再將出現的小視窗直接關閉即可。","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:90162"]={"id":"error:90162","ty":"error","sourceId":"90162","title":"connect error","ver":"GP4.0.2.0","topic":"","job":"採購單憑證","cause":"因為電腦尚未安裝office","solution":"請重新安裝ofiice後即可。","quoted":true,"file":"errors.jsonl"};
self.KB_CONTENT["error:831572"]={"id":"error:831572","ty":"error","sourceId":"831572","title":"『空白發票未使用批次匯出作業-EINB05』按確定後會跳出 \"總公司:XXXXX無法批次執行\"，該如何排除","ver":"GP4.0.26.0以上","topic":"","job":"空白發票未使用批次匯出作業","cause":"","solution":"需檢查『電子發票中介區查詢作業-EINQ05』於第四個頁籤【加值中心參數設定查詢】中可查看到合約區間，倘若要上傳的電子發票不在開通區間內，需到財政部電子發票整合平臺自行維護。 倘若已過期需要展延汎宇合約，請洽業務協助處理。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:830096"]={"id":"error:830096","ty":"error","sourceId":"830096","title":"『新品號申請建立作業』作廢以後，可以重新新增嗎","ver":"GP4.0.16.0以上","topic":"","job":"新品號申請建立作業","cause":"","solution":"『新品號申請建立作業』作廢以後，無法新增一樣的品號，因為此欄位在系統是唯一性，不可以重覆存在.","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:851673"]={"id":"error:851673","ty":"error","sourceId":"851673","title":"『會計傳票建立作業』點選【傳票單筆過帳/還原】要進行傳票過帳，但會跳出錯誤訊息''該年期或會計關帳年期之會計期間未設定''","ver":"GP40.iGP 以上","topic":"","job":"會計傳票建立作業","cause":"","solution":"可以查看『會計期間設定作業-ACTI07』是否有包含會計傳票該年度的資料，若沒有需補入年度資料後續在『會計傳票建立作業-ACTI10』點選ICON【傳票單筆過帳/還原】即可過帳","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:889885"]={"id":"error:889885","ty":"error","sourceId":"889885","title":"『資產資料建立作業』的【取得成本】、【累積折舊】、【帳面價值】、【殘值】...，與金額相關的欄位是灰色的不能輸入","ver":"GP4.0.18.0以上","topic":"","job":"資產資料建立作業","cause":"","solution":"『資產資料建立作業』的【取得成本】、【累積折舊】、【帳面價值】、【殘值】...，與金額相關的欄位是灰色的不能輸入？ 請在『使用者權限建立作業』將資產資料建立作業的【售價權限】將權限改為\"一般\"","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:817293"]={"id":"error:817293","ty":"error","sourceId":"817293","title":"『碳盤監控明細表』【警示碳排量(年)】如何計算","ver":"AIGP","topic":"","job":"碳盤監控明細表","cause":"","solution":"抓報表【減排設定總碳排量】*【警示目標(年)】=【警示碳排量(年)】","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:816799"]={"id":"error:816799","ty":"error","sourceId":"816799","title":"『銀行存款存提作業-NOTI02』新增時會出現「輸入的銀行帳號並不存在」","ver":"IGP1.0.2.0以上","topic":"","job":"銀行存款存提作業","cause":"由於【帳號對象資料建立】沒有該廠商銀行帳號。","solution":"可到基本資料管理系統->建立作業->開啟『金融機構建立作業-CMSI16』，點選右邊【帳號對象資料建立】功能鈕，再點選【維護】新增本次對象的銀行帳號資料即可。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:881333"]={"id":"error:881333","ty":"error","sourceId":"881333","title":"一筆進貨單是否可以對應產生兩筆應付憑單，以實現分批付款","ver":"AiGP 1.1.3","topic":"","job":"","cause":"進貨單序號不可重複，且一筆進貨單單身無法直接拆分為多筆應付憑單。","solution":"拆分進貨單：至『進貨單建立作業』，將原進貨單單身拆分為多筆不同序號，即可分別開立應付憑單。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:870687"]={"id":"error:870687","ty":"error","sourceId":"870687","title":"小平台檢核失敗顯示「發票號碼不在所設定的發票區間內」時，應如何確認與處理","ver":"GP4.0.21.1","topic":"","job":"","cause":"分支機構配號資料、發票本設定或配號匯出資料未同步，可能導致發票號碼與系統設定區間不一致。","solution":"1. 確認「分支機構配號檔」是否已有正確資料。 2. 檢查「每月發票建立作業」是否已建立並使用發票區間。 3. 確認是否重新執行「分支機構配號檔批次匯出作業」。 4. 將失敗資料取回後重新上傳。 5. 重新檢核小平台上傳結果。 【其他補充】若曾手動維護每月發票資料但未重新匯出配號檔，可能造成檢核失敗。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:817792"]={"id":"error:817792","ty":"error","sourceId":"817792","title":"已產生預約付款，但臨時收到通知不付款了 ，要與應收帳款互抵請問該如何處理","ver":"GP4.0.16 以上","topic":"","job":"","cause":"","solution":"說明直接到『預計收支建立作業->NOTI05』將資料刪除即可(因為實現沒有被勾選且沒有銀行存提的單別單號)，後續登打一張付款單將借貸科目回轉即可","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:878900"]={"id":"error:878900","ty":"error","sourceId":"878900","title":"出貨通知單更新作業視窗\"選擇生產\"點選\"暫出單\"，再\"輸入暫出單單別\"後出現錯誤訊息\"此單別不存在或單據性質不符!\"","ver":"GP4 以上","topic":"","job":"","cause":"","solution":"請確認庫存管理系統->『單據性質設定作業-INVI04』中，該單別是否有設定【單別限定輸入使用者】，如有勾則使用者代號要補進去，後續才可使用該單別。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:840543"]={"id":"error:840543","ty":"error","sourceId":"840543","title":"生產入庫單可否判斷未領料不能入庫","ver":"iGP 1.0.15以上","topic":"","job":"","cause":"","solution":"生產入庫單若要卡控未領料不能入庫，可於『單據性質設定作業』將該入庫單別的【控制缺領】=Y.控制缺領","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:881614"]={"id":"error:881614","ty":"error","sourceId":"881614","title":"用ERP切換公司別時，會出現「取訊息數量時發生錯誤:Socket Error #10060 Connection timed out」 >>協助到「服務」重新啟動「SMERPCallBackService」後還是一樣","ver":"iGP 1.0.18以上","topic":"","job":"","cause":"","solution":"查看 DB主機IP 192.168.1.112，但是ConductorX64\\s_dsbin\\Sevicemanager裡設定的CallbackService IP為192.168.1.113，調整為192.138.1.112，重啟ERPCallBackService","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:828048"]={"id":"error:828048","ty":"error","sourceId":"828048","title":"再多公司資料建立作業，無法新增公司","ver":"GP4 以上","topic":"","job":"","cause":"","solution":"請透過基本資料管理系統->管理維護作業->『新公司資料複製作業』複製產生新公司","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:811383"]={"id":"error:811383","ty":"error","sourceId":"811383","title":"同張費用單分兩次付款,第二次付款無法產生提款單","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"說明一張費用申請單僅能對應一張提款單 若要分次去提款有兩種方式： 方式一:批次產生提款單時，提款金額手動修改，後續第二次付款時手動建立第二張提款單，並於備註記錄為哪張費用申請單。 方式二:將金額拆開兩張費用申請單，分別產生提款單。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:872313"]={"id":"error:872313","ty":"error","sourceId":"872313","title":"在執行傳票整批過帳作業時，於【基本選項】【選擇傳票日期】輸入2026/01/01，跳出錯誤訊息\"該年期或會計關帳年期之會計期間未設定!\"，要如何處理","ver":"iGP 1.0.5.以上","topic":"","job":"基本選項","cause":"","solution":"可到會計總帳管理系統->基本資料管理->『會計期間設定作業』，在此新增，【年度】輸入【2026】、【年度起始日期】下【2026/01/01】，點選單身，系統會自動帶入12期資料，存檔後即可再次執行『傳票整批過帳作業』。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:871114"]={"id":"error:871114","ty":"error","sourceId":"871114","title":"如何刪除已確認訂單單身的序號","ver":"GP4.0.8.0 以上","topic":"","job":"","cause":"","solution":"可透過『訂單變更單建立作業』將【品號】指定結案，無法直接刪除訂單序號","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:874412"]={"id":"error:874412","ty":"error","sourceId":"874412","title":"如果是2025年做的託外進貨單，已經完工，但於2026年要做退貨，已經跨年度故在執行此作業時，系統會出現錯訊\"退貨月份不可大於此製令之完工月份\"","ver":"iGP 1.0.8.以上","topic":"","job":"","cause":"","solution":"1.該月份是否有同品號同供應商託外製令，將退貨打在該製令託外退貨上。 2.新增庫存異動Y.單退品號庫存數量與金額，再手動打應付憑單反應廠商退款。 3.新增重工工單，領自己再打託外進貨入庫(不要輸入加工單價)，最後再打託外退貨(賦予退貨加工單價)。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:871969"]={"id":"error:871969","ty":"error","sourceId":"871969","title":"如果某張訂單客戶已經預付貨款，但因為信用額度的控制，導致客戶訂單建立作業無法確認，有沒有甚麼解決方式","ver":"GP4以上","topic":"","job":"","cause":"","solution":"若新增訂單時因為信用額度卡控無法確認，可先於『客戶資料建立作業』【交易資料(一)】的「訂單確認時，信用查核超限處理方式」由【拒絕】改為【警告】或【不檢查】。 設為【警告】：確認訂單時，會跳出警告視窗「金額 XXX 不可大於信用餘額 XXX」，但仍可確認訂單。 設為【不檢查】：確認訂單時，不會跳出任何視窗，可直接確認訂單。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:843876"]={"id":"error:843876","ty":"error","sourceId":"843876","title":"收款單幣別無法變更","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"請將『收款單建立作業』單頭【幣別】欄位清空，單身可帶入不同幣別資料","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:852456"]={"id":"error:852456","ty":"error","sourceId":"852456","title":"有一個品號無法刪除","ver":"iGP 1.0.9.","topic":"","job":"","cause":"","solution":"若欲刪除的品號已經請採進，可到進貨單刪除此品號再作廢單據，並至採購單查詢單據刪除要刪除之品號，存檔後，可回到品號資料建立作業點擊修改刪除單身品號後存檔，再刪除品號。刪除品號的前提是品號不可有任何異動單據及庫存。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:864332"]={"id":"error:864332","ty":"error","sourceId":"864332","title":"夾了檔案，送核一直無法成功","ver":"GP4.0.8.0 以上","topic":"","job":"","cause":"","solution":"單據夾帶附件後無法送簽請檢查: (1)送簽USER與電派主機(有開啟電子表單派班中心的主機)的conductor\\S_dsbin\\DMSS.INI內路徑是否相同? 路徑是否都有通? (2)於電派主機登入ERP開啟後找到該單據，是否可打開附件? 如果送簽USER電腦設定的DMSS.ini路徑不通，請改成正確路徑且確定有通後，到『電子表單佇列工作建立ADMI13』刪除『電子表單佇列工作建立ADMI13』該單據的送簽紀錄並重新夾附件送簽。 (註)DMSS.ini路徑不通:例如conductor\\S_dsbin\\DMSS.ini檔最後一行設定【FileServerUNC=\\\\192.168.1.001\\DocLibrary】，代表「\\\\192.168.1.001\\DocLibrary」是存放附件的路徑，將此路徑複製貼上到送簽USER電腦的資料夾後按下ENTER，如果可以跳轉到共用資料夾代表有通，如果跳出錯誤訊息或是跳出要輸入帳號密碼代表不通。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:828260"]={"id":"error:828260","ty":"error","sourceId":"828260","title":"更打訂單時會出現，【此人員不存在或職務分類不符】的錯誤訊息","ver":"GP4 以上","topic":"","job":"此人員不存在或職務分類不符","cause":"","solution":"『客戶基本資料』【業務人員】為0022，查看『職務類別建立作業』在業務分類並無該【業務人員】，新增0022後，重新更打訂單已可以順利帶出該【業務人員】","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:877387"]={"id":"error:877387","ty":"error","sourceId":"877387","title":"材料品號在『品號成本低階碼維護作業』維維護完，執行『成本低階碼計算更新作業』又恢復錯誤訊息E:材料品號低階碼小於產品品號低階碼","ver":"WFGP4.0.27以上","topic":"","job":"品號成本低階碼維護作業","cause":"","solution":"材料品號在『品號成本低階碼維護作業』維護低階碼後，就不要執行『成本低階碼計算更新作業』，否則低階碼會被更新回去","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:871947"]={"id":"error:871947","ty":"error","sourceId":"871947","title":"沒有產生訂單 直接銷貨，後續要退貨，但登打銷退單時，顯示訂單單別、單號、序號不可空白","ver":"GP4以上","topic":"","job":"","cause":"因該銷退單別在『單據性質設定作業-COPI03』有勾選【核對訂單】，因此登打銷退單且訂單單別、單號、序號空白時，會跳出錯誤訊息。","solution":"若是無登打訂單的銷貨要做銷退，建議在單據性質設定作業新增一張無核對訂單的銷退單別即可。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:846794"]={"id":"error:846794","ty":"error","sourceId":"846794","title":"使用下角料（無進料紀錄）製作兩張BOM母件，是否可設為不發料；另委外加工僅收加工費並需計算工時，如何處理","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"實務為以廢料投入、不需扣發正式用料；另委外流程僅認列加工費與工時，不需材料進退帳。","solution":"1. 於BOM將相關用料設定為「不發料」以免扣庫。 2. 建立委外（外包）流程，母件走委外單，僅計入加工費（例：5107單別）。 3. 於委外或工時模組維護工時參數，記錄並計算成本。 4. 盤點前核對在製與委外在途，避免影響基準量。 【其他補充】：若下角料仍需成本追蹤，得以替代料或費用方式入帳再統一調整。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:849777"]={"id":"error:849777","ty":"error","sourceId":"849777","title":"取消過帳出現：該年期或會計關帳期間未設定，應如何","ver":"IGP 以上","topic":"","job":"","cause":"","solution":"請至基本資料管理系統 -> 基本資料管理 -> 『共用參數設定作業-CMSI01』的【財務參數設定】頁簽，確認以下欄位的設定： 【會計現行年度】 【會計現行期別】 【會計關帳年度】 【會計關帳期別】 2.設定會計期間：請至會計總帳管理系統 -> 基本資料管理 -> 『會計期間設定作業-ACTI07』，新增會計期間。 確認【會計現行年度】和【會計關帳年度】的會計期間資料是否已設定。 例如：會計關帳年度/期別是“2024/12”，會計現行年度/期別是“2025/01”，則『會計期間設定作業』請新增2024和2025二個年度，單身期別點一下會自動展出1～12期，存檔再重新進行原作業即可。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:812416"]={"id":"error:812416","ty":"error","sourceId":"812416","title":"品號資料的屬性組代碼無法修改","ver":"GP4.0.18.0以上","topic":"","job":"","cause":"","solution":"『品號資料建立作業』\\屬性類別頁 【屬性組代碼】只有在\"新增\"『品號資料建立作業』時，才可以輸入【屬性代碼組】欄位，若是在\"修改\"狀態下才會反灰，無法修改 可到『品號資料屬性組合建立作業-INVI28』將該品號查詢出來後修改即可","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:860686"]={"id":"error:860686","ty":"error","sourceId":"860686","title":"建立者的工號怎麼會出現與EF段的回寫填表人不同呢","ver":"iGP1.1.0.0以上","topic":"","job":"","cause":"","solution":"建立者:該單據建立人員 填表人:於該單據點選\"確認送簽\"的人員 確認者:最後在EF上簽核該單據的人員 以上三個欄位都沒有強制關聯要一致，EX:銷貨單由A建立，因A人員休假B人員代理送簽，B人員主管C人員於EF上簽核 則此單據建立者為A，填表人為B，確認者為C","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:878540"]={"id":"error:878540","ty":"error","sourceId":"878540","title":"建立銷貨單複製前置訂單時，畫面一直跳出付款條件通知且無法儲存","ver":"AiGP1.1 以上","topic":"","job":"","cause":"因來源客戶訂單之「付款條件」欄位留空；至『客戶訂單建立作業』補齊付款條件，重新複製帶入銷貨單後即可正常儲存過單。","solution":"","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:877093"]={"id":"error:877093","ty":"error","sourceId":"877093","title":"某些單據無法自動拋轉傳票","ver":"GP40.iGP 以上","topic":"","job":"","cause":"","solution":"若單據性質已設定，但仍無法自動拋轉傳票，請檢查以下幾點： 1. 單據金額是否為0，若為0則無法產生傳票。 2. 自動分錄系統->『分錄性質設定』中是否已正確設定該作業的單別。 3. 執行自動分錄系統->基本資料管理->『分錄底稿產生作業』時條件是否符合。 4. 主機派班中心是否開啟並有勾選[定時處理]。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:890591"]={"id":"error:890591","ty":"error","sourceId":"890591","title":"派班中心出現重啟後出現已離職員工的使用者代號跟+工作代號是2020的日期，出現多筆","ver":"IGP","topic":"","job":"","cause":"","solution":"可開啟佇列工作控制台，點選【週期性】確認是否有該人員設定的資料，若不需要可點選工具列中的【週期終止】，之後就不會再執行了。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:810924"]={"id":"error:810924","ty":"error","sourceId":"810924","title":"為何進貨單都驗收完畢但要刪除進貨單卻無法刪除","ver":"iGP1.0.8.0以上","topic":"","job":"","cause":"","solution":"如果『進貨單建立作業-PURI09』要刪除單據無法刪除，如果單身品號有做驗收，可以先檢查『進貨驗收作業-PURI13』是否有存在已驗收的「進貨驗收單」，如果有需先將進貨驗收單取消確認，後續在回到『進貨單建立作業-PURI09』即可刪除進貨單單據。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:815725"]={"id":"error:815725","ty":"error","sourceId":"815725","title":"庫存 單據性質設定作業 的【影響成本碼】無法修改","ver":"iGP 1.0.14以上","topic":"","job":"影響成本碼","cause":"","solution":"庫存的『單據性質設定作業-INVI04』的【影響成本碼】欄位單別新增後即無法修改，因如果單別已使用過修改設定就會造成之前異動增減有誤，建議如有需求可以再另外新增單別做設定。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:868039"]={"id":"error:868039","ty":"error","sourceId":"868039","title":"庫存明細表出現多筆同一品號資料的處理方法","ver":"GP4.0.11.0","topic":"","job":"","cause":"","solution":"當庫存明細表中出現多筆同一品號資料時，若透過單據調整，品號資料建立作業單身庫別仍會存在，但數量會呈現0，無需刪除該資料。在執行進耗存統計表時，可以於進階選項中取消勾選【列印各庫明細】，這樣後續執行報表時只會顯示一筆資料。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:840037"]={"id":"error:840037","ty":"error","sourceId":"840037","title":"能否用鼎新後臺直接匯入單據資料","ver":"GP4.0.27.0以上","topic":"","job":"","cause":"","solution":"目前系統的單據都沒有提供匯入的功能，避免資料異常，若有長期需要建議詢問顧問客製程式，可能會有費用產生。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:820079"]={"id":"error:820079","ty":"error","sourceId":"820079","title":"能否針對特定倉別，鎖定只有特定使用者能使用轉撥此倉別的權限","ver":"GPGP4.0.16以上","topic":"","job":"","cause":"","solution":"以系統標準程式邏輯，目前無參數或作業可設定使用者無法選取某庫別之設定。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:840103"]={"id":"error:840103","ty":"error","sourceId":"840103","title":"退貨折讓單為什麼無法登打數量","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"折讓的退貨單，於『退貨單建立作業』中單身【類型】挑選【2.折讓】，不需輸入數量，只需維護【金額】欄位，針對要折讓的金額維護即可。當類型為【2.折讓】，【數量】為0不影響金額計算。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:879073"]={"id":"error:879073","ty":"error","sourceId":"879073","title":"送簽時即使是超級使用者也無法產生憑證圖檔，無法送簽 憑證代號:PURR07 無法產生憑證圖檔 ERROR MSG","ver":"GP4.0.27.0以上","topic":"","job":"","cause":"","solution":"請確認主機的控制管理→元件VRLeader(或EFWorkCenter.exe)有無卡住。如果有，可以結束此工作。重新送簽看看。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:866860"]={"id":"error:866860","ty":"error","sourceId":"866860","title":"執行『外幣存款月底重評價表』按確認會顯示''尚有未確認之匯兌損益調整單,不可勾選擇自動產生功能''","ver":"GP40.iGP 以上","topic":"","job":"外幣存款月底重評價表","cause":"因在『匯兌損益調整-NOTI17』還有單據未確認，因此在『外幣存款月底重評價表-NOTR25』不能勾選【自動產生匯兌損益調整單】","solution":"","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:881377"]={"id":"error:881377","ty":"error","sourceId":"881377","title":"採購單有確認、對應的進貨單也確認，進貨數量正確，但採購單卻沒有自動結案，請問要如何處理","ver":"iGP 1.0.17以上","topic":"","job":"","cause":"","solution":"可執行採購管理系統->批次作業->『採購已交量重計作業』，【選擇採購單號】起迄輸入該單號，執行完畢後即可看到【結案碼】變為【Y:自動結案】。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:811660"]={"id":"error:811660","ty":"error","sourceId":"811660","title":"啟動 Leader 工作元件中心錯誤","ver":"GP4.0.21.0以上","topic":"","job":"","cause":"","solution":"請檢查c_dsbin\\LeaderWorkCenterC.exe是否不存在1.檢查Conductor\\c_dsbin\\LeaderWorkCenterC.exe，如不存在，請從別台電腦複製過來。如存在，請直接進行步驟二。 步驟二：進行公用元件重新註冊請開啟Conductor\\Dsupate進行公用元件重新註冊","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:854843"]={"id":"error:854843","ty":"error","sourceId":"854843","title":"現金流量表檢查表出現已作廢的傳票","ver":"GP4.0.17.0以上","topic":"","job":"","cause":"","solution":"請執行會計總帳管理系統->現金流量表->『現金流量表資料產生作業-ACTB24』勾選\"已產生者重複產生\"","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:867276"]={"id":"error:867276","ty":"error","sourceId":"867276","title":"處理銷貨單複製前置單據時數量為0及沖抵金額錯誤","ver":"iGP1.1.0.0","topic":"","job":"","cause":"當複製前置單據帶入訂單時，若銷貨單的單身數量顯示為0，可能是因為該訂單已交量大於庫存數量。","solution":"請檢查庫存數量是否足夠。若庫存不足，需手動調整銷貨單的數量。此外，若在銷貨單中輸入數量後存檔時出現‘沖抵金額不可大於原幣銷貨金額’的錯誤訊息，請手動修改沖抵金額，使其等於或小於原幣銷貨金額。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:864714"]={"id":"error:864714","ty":"error","sourceId":"864714","title":"無法列印供應商資料時如何開啟列印功能","ver":"GPGP4.0.22","topic":"","job":"","cause":"","solution":"當供應商資料無憑證時，無法直接列印。建議採取以下方法解決：1.將供應商資料轉出至Excel進行列印。2.透過供應商資料清單進行列印。3.透過供應廠商檢索表進行列印。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:862011"]={"id":"error:862011","ty":"error","sourceId":"862011","title":"無法開啟佇列工作控制台","ver":"GP4.0 以上","topic":"","job":"","cause":"","solution":"工作管理員->QueueManagerC.exe元件有卡住的狀況，點選右鍵【結束工作】，已可開啟佇列工作控制台。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:830492"]={"id":"error:830492","ty":"error","sourceId":"830492","title":"無法開啟workflow ERP","ver":"GP4.0.8.0 以上","topic":"","job":"","cause":"","solution":"找到Conductor資料夾底下的Dsupdate.exe執行點選【選擇部分檔案】，中間的項目都不要勾選，勾選【公用元件重新註冊】，按下載程式，待進度條跑完即可正常登入系統。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:834012"]={"id":"error:834012","ty":"error","sourceId":"834012","title":"無法複製報價單憑證格式到其他臺電腦","ver":"iGP 1.0.5.以上","topic":"","job":"","cause":"","solution":"請先至ConductorConductorC.ini中查看憑證路徑【RTBuilderDataPath】，並到該路徑資料夾中複製憑證格式(憑證檔名：Tfrm程式代號Fmt_憑證使用格式.dat)，複製到另外一台的ConductorC.INI設定的憑證資料夾(預設C_data資料夾)內即可。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:844077"]={"id":"error:844077","ty":"error","sourceId":"844077","title":"登入ERP系統啟動時出現錯誤，無法正常登入系統","ver":"GP4.0.18.0以上","topic":"","job":"","cause":"","solution":"請執行公用元件重新註冊，請按照以下步驟操作： 1.找到Conductor資料夾底下的 Dsupdate.exe。 2.以滑鼠右鍵點擊 Dsupdate.exe，選擇「以系統管理員身分執行」。 3.在「選擇來源路徑」中，選擇本機的Conductor安裝路徑。 4.點選「選擇部分檔案」，在彈出的選項中，僅勾選「公用元件重新註冊」，其餘選項不要勾選。 5.點選「下載程式」，等待進度條完成即可。 完成以上步驟後，公用元件重新註冊就完成了。WorkFlowERP即可正常進入系統。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:861267"]={"id":"error:861267","ty":"error","sourceId":"861267","title":"費用申請單無法順利拋轉會計傳票，應如何排查原因","ver":"iGP 以上","topic":"","job":"","cause":"(1) 自動分錄之分錄性質（PCMI12）未設定對應單別；(2) 單據中登入的部門代號未在「部門權限設定」或會計科目允許的部門名單內。","solution":"【解決方案】檢查分錄底稿中的部門代碼，確認該部門已存在於系統「部門資料建立作業」中，且具備相關拋轉權限。修正部門資訊後，重新產生分錄底稿並拋轉傳票即可。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:884147"]={"id":"error:884147","ty":"error","sourceId":"884147","title":"跑即時報表跑不出來","ver":"AiGP1.1 以上","topic":"","job":"","cause":"","solution":"請檢查預設印表機的驅動程式是否不是原廠相同型號的驅動程式，安裝為原廠的印表機驅動程式","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:829902"]={"id":"error:829902","ty":"error","sourceId":"829902","title":"進貨單的有效日期能不能預設空白","ver":"GP4 以上","topic":"","job":"","cause":"","solution":"『進貨單建立作業-PURI09』單身的【有效日期】會預設帶入『品號資料建立作業-INVI02』的【有效天數】+『進貨單建立作業-PURI09的【單據日期】，若不希望帶有效日期，需手動把【有效日期】欄位清空","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:886808"]={"id":"error:886808","ty":"error","sourceId":"886808","title":"進貨單單據日與單身驗收日不同月份，為何送簽時未阻擋，直到簽核最後一關才跳出卡控錯誤","ver":"GP4.0.24.0","topic":"","job":"","cause":"電子簽核送件僅做表單傳送，單據商業邏輯檢核係於最終關卡核准呼叫 ERP 確認員時觸發。","solution":"單據送出簽核時僅為在途草稿，系統是在簽核全數通過、回寫 ERP 呼叫「單據確認員」的當下，才正式執行關帳年月檢核。2.排查關帳年月限制：檢查單身【驗收日期】是否小於當前之【庫存現行年月】或小於【帳務凍結日期】。3.修正驗收日期：將進貨單單身之驗收日期修改調整為未關帳之有效月份。4.重新送簽審核，最終關卡即可順暢通過確認。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:864400"]={"id":"error:864400","ty":"error","sourceId":"864400","title":"進貨單無法刪除單身資料","ver":"iGP 1.0.11以上","topic":"","job":"","cause":"","solution":"請先確認『進貨單建立作業-PURI09』單身序號是否有已確認的進貨驗收單，若有，需將『進貨單驗收作業-PURI13』取消確認，再回到進貨單將單身刪除。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:867474"]={"id":"error:867474","ty":"error","sourceId":"867474","title":"進貨數量為0無法取消確認進貨單","ver":"iGP 1.0.9.","topic":"","job":"","cause":"當進貨數量為0時，若系統顯示無法取消確認進貨單，可能是因為供應廠商資料建立作業中未勾選「允許分批交貨」。","solution":"這會導致即使進貨數量為0，系統仍將採購單結案，因此無法取消確認進貨單。解決方法是將未進貨的品項重新建立新的採購單和進貨單。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:882985"]={"id":"error:882985","ty":"error","sourceId":"882985","title":"開帳單據匯入後無法正確計算單位成本，應檢查哪些欄位","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"開帳單據若僅匯入金額，未依規定填入材料、人工及製費等成本結構明細，系統將無法計算單位成本，請重新檢視開帳匯入檔，補齊料工費成本拆分數字後重新匯入更新。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:834676"]={"id":"error:834676","ty":"error","sourceId":"834676","title":"想請問，業務這邊發現訂單的金額有誤，想要取消確認修改金額時跳出「此單據已有製令單號，無法取消確認」，現在應該怎麼修改金額比較好? 直接在銷貨單修改金額","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"建議可以打訂單變更單修改金額","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:868659"]={"id":"error:868659","ty":"error","sourceId":"868659","title":"新公司別於會計傳票建立作業中查無會計科目選項，應如何處理","ver":"GP4.0.17.1","topic":"","job":"","cause":"新公司別尚未建立或複製會計科目檔資料。","solution":"1. 開啟【公司別基本資料複製作業】。 2. 選擇來源公司別。 3. 勾選會計科目檔資料。 4. 執行複製作業至新公司別。 5. 重新進入【ACTI10 會計傳票建立作業】確認科目選項。 【其他補充】不同公司別需各自建立會計科目資料，未建立時將無法選取會計科目。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:815691"]={"id":"error:815691","ty":"error","sourceId":"815691","title":"當初進料的時候打錯倉，進成專案倉，該怎麼退回去變成寄外倉","ver":"GP4.0.21.0以上","topic":"","job":"","cause":"","solution":"可以先登打『退貨單』將數量退回原本錯誤的庫別，再重新登打一張新的『進貨單』入庫到正確的庫別。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:864857"]={"id":"error:864857","ty":"error","sourceId":"864857","title":"解決品號變更建立作業中儲存後無法直接確認的問題","ver":"GP4.0.13.0","topic":"","job":"","cause":"","solution":"當在品號變更建立作業中輸入新規格並儲存後，若遇到無法直接執行確認的情況，請前往管理維護系統->資料管理->(程式代號建立作業-ADMI02)，查詢INVI24並勾選【執行畫面保留碼】。完成此步驟後，即可正常進行確認操作。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:867720"]={"id":"error:867720","ty":"error","sourceId":"867720","title":"解決Pokemon發票無法生成的問題","ver":"GP4.0.20.0","topic":"","job":"","cause":"","solution":"當嘗試生成Pokemon發票時，如果選擇轉出Excel選項後出現「寫資料到EXCEL失敗」的錯誤訊息，可以按照以下步驟進行排查和解決：1.確認Excel應用程式是否已正確安裝並能夠正常啟動。2.檢查是否有足夠的磁碟空間來保存生成的Excel檔案。3.確保使用的Excel版本與系統相容。4.嘗試關閉所有正在運行的Excel實例，然後重新執行發票生成操作。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:859062"]={"id":"error:859062","ty":"error","sourceId":"859062","title":"電子發票上傳失敗異常E001處理方法","ver":"GPGP4.0.3.","topic":"","job":"","cause":"","solution":"當遇到電子發票上傳失敗，顯示異常E001:發票日期不在中介區的有效日期區間裡時，首先需要確認是否已經聯繫業務請汎宇延長有效日期。若已延長，可重新上傳電子發票。上傳後，確認發票是否已顯示在大平臺並上傳成功。此外，可以查看EINI10的處理結果，若仍有疑慮，可至財政部網站查詢確認。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:865137"]={"id":"error:865137","ty":"error","sourceId":"865137","title":"電子發票字軌編配表建立時出現作業元件TAXI08無法載入","ver":"iGP 1.0.13","topic":"","job":"","cause":"","solution":"當在進行電子發票字軌編配表建立時，若遇到作業元件TAXI08無法載入的問題，可以按照以下步驟解決：首先，前往雲管家或資訊中心下載115年度發票字軌。接著，使用TAXB15工具匯入發票字軌。最後，在每月發票資料建立作業中新增發票本。若需要進一步瞭解如何生成2026年發票字軌，可參考官方提供的指引：http://es-ygj.digiwincloud.com/scpcontroller?datasource=TW&op=kbshare&opid=1879582&kbid=848164&serviceregions=TW","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:849997"]={"id":"error:849997","ty":"error","sourceId":"849997","title":"電子發票憑證列印的\"列印贈/備品量\"反灰無法勾選","ver":"GP4 以上","topic":"","job":"","cause":"","solution":"請於『電子發票列印/上傳參數設定作業-EINI06』的【批次條件名稱六(列印贈/備品量)】打勾，後續『電子發票憑證列印-COPR77』即會預設勾選列印贈/備品量","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:872043"]={"id":"error:872043","ty":"error","sourceId":"872043","title":"管藥憑證無法在系統選項輸入AA變成鼎新預設格式","ver":"AiGP1.1 以上","topic":"","job":"","cause":"","solution":"請於『單據性質建立作業(訂單)』中查詢該單別勾選【列印時選擇憑證格式】","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:814375"]={"id":"error:814375","ty":"error","sourceId":"814375","title":"製令沒有領料，領料單身出現負值","ver":"GP4 以上","topic":"","job":"","cause":"","solution":"可執行『製令領料重計作業MOCB01』，重計該筆製令後狀況就會正常","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:861960"]={"id":"error:861960","ty":"error","sourceId":"861960","title":"製令單身沒有材料品號，無法領料","ver":"GP4.0.17.0以上","topic":"","job":"","cause":"","solution":"請先於製令/託外管理系統->日常異動處理->『製造命令變更建立作業』新增一筆資料，單身【原材料品號】補滿”*”星號，在【材料品號】欄位按[F3]開窗選取，或直接輸入欲加入的品號，單據確認後即會自動回寫到『製造命令建立作業』中。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:809409"]={"id":"error:809409","ty":"error","sourceId":"809409","title":"製令領料數量卡住","ver":"GP4.0.23.0以上","topic":"","job":"","cause":"","solution":"查看製令單身有已領用量，但串查製令樹狀資訊查詢，並無領料單，執行『製令領料重計作業』即可","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:809445"]={"id":"error:809445","ty":"error","sourceId":"809445","title":"製令變更單是否可以整批修改單身原材料品號庫別","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"登打製令變更單，只能逐筆修改原材料庫別，無法整批修改。 子單頭的【製令用料重計】，僅能針對【新增材料品號時選擇庫別】，無法針對原有品號修改。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:867650"]={"id":"error:867650","ty":"error","sourceId":"867650","title":"製令變更無法確認\"製令有已領用量或未確認領料數量,不可變更材料型態為 4.不發料!\"","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"如果有存在一筆未確認的領料單資料，需刪除領料單後，重新確認製令變更","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:841038"]={"id":"error:841038","ty":"error","sourceId":"841038","title":"領料單無法拋分錄","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"可先確認領料單的領料數量是否為0?若數量為0*單位成本金額還是0，就無法拋轉分錄。(可檢查『異動明細維護作業』查領料單確認金額)","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:837066"]={"id":"error:837066","ty":"error","sourceId":"837066","title":"暫出/入單建立作業可儲存，但確認時，出現錯誤訊息「品號[XXXX]產品序號[XXXXXXXXX]不存在或已出庫或已被製令預定,不可出庫!」","ver":"GP4以上","topic":"","job":"","cause":"原因：因作業中所輸入的品號產品序號不存在『產品序號建立作業-RMAI10』中，或已出庫，或已被製令預定(I/O別為“空白(預定)”)，所以不可出庫。","solution":"可到產品序號管理系統->基本資料管理->『產品序號建立作業-RMAI10』查詢此【品號】+【產品序號】目前的狀況，是否有最後一筆I/O別為“O”，或是為“空白(預定)”的資料，如果有，就不可以做出庫。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:846637"]={"id":"error:846637","ty":"error","sourceId":"846637","title":"盤盈成品序號入庫時提示序號已存在/已被預定，單據無法確認，如何處理","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"該序號最後一次I/O為O且異動別非1.入庫，導致再次以入庫或調整類型入庫被系統拒絕。","solution":"1. 於『產品序號建立作業』查詢該序號最後I/O與異動別。 2. 若最後I/O為O且非入庫，改以『異動類別＝領用』『影響庫存＝增』之單別入庫。 3. 重新確認單據並檢查序號狀態為可用。 4. 建立序號異動稽核報表，避免重複入庫。 【其他補充】：序號邏輯以最後一次I/O及異動別為準，入庫路徑須符合規則。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:871172"]={"id":"error:871172","ty":"error","sourceId":"871172","title":"盤點后更新完，也有自動調整庫存，庫存爲什麼還是不足","ver":"AiGP1.1 以上","topic":"","job":"","cause":"","solution":"請先確認『進耗存統計表INVR19』本期期初數量是否與上期期末數量相符，如有不符，可能導致本期數結餘量錯誤出現負數狀況。請執行『現有庫存重計作業INVB02』，重計年月=上期月份。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:846655"]={"id":"error:846655","ty":"error","sourceId":"846655","title":"盤點底稿出現負數，但歷史帳彙總為相符，如何判斷與修正（例：入庫有批號、領料未帶批號）","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"入庫以批號入帳但領料未帶批號，致批號帳與總帳分離，底稿顯示負數。","solution":"1. 追查同一品號各批號之入出庫一致性，找出未帶批領料。 2. 以盤盈損單或批號調整將數量回補至正確批號。 3. 建立領料必填批號規則並加強掃描/稽核。 4. 重新產生盤點底稿，確認負數已排除。 【其他補充】：對曾發生批號不一致的品項建立監測報表。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:846871"]={"id":"error:846871","ty":"error","sourceId":"846871","title":"盤點調整單想取消確認時出現庫存不足，該如何處理","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"盤點後又有出庫（如銷貨），回滾時庫存量不足以支撐取消確認。","solution":"1. 優先取消後續銷貨/出庫等相關單據之確認。 2. 再執行盤點調整單取消確認。 3. 重新檢核盤點資料並按流程更新。 4. 若不得取消後續單據，改以新建調整單補差。 【其他補充】：作業前先鎖定盤點時點，避免產生回滾斷點。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:889368"]={"id":"error:889368","ty":"error","sourceId":"889368","title":"複製訊息的功用是什麼呢","ver":"GP4.0.0.0 以上","topic":"","job":"","cause":"","solution":"複製訊息可以複製單據發生的錯誤訊息，複製貼上給資訊或交由客服人員查閱錯誤使用 。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:813301"]={"id":"error:813301","ty":"error","sourceId":"813301","title":"請問有一個品號入庫A儲位，但目前該庫別無儲位A，請問該如何將此庫存移轉至正確的儲位","ver":"GP4.0.14.0以上","topic":"","job":"","cause":"","solution":"請至基本資料管理系統->建立作業『庫別資料建立作業』檢查該儲位代號是否存在於該庫別單身儲位資料。若該儲位不存在，請先新增該儲位。新增完畢後，再執行庫存移轉作業，將該品號的庫存從目前的錯誤儲位移轉至正確的儲位。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:814762"]={"id":"error:814762","ty":"error","sourceId":"814762","title":"請購單建立作業出現訊息類別：E 代號：XXXXX不存在 !這該如何解決呢","ver":"iGP1.0.3.0以上","topic":"","job":"","cause":"","solution":"ERP主畫面->『工作管理員』->『訊息管理』頁籤點選【更新訊息】進行中文(繁體)更新訊息檔。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:836106"]={"id":"error:836106","ty":"error","sourceId":"836106","title":"銷退單為什么不能到結賬單那里","ver":"GP4.0.20.0以上","topic":"","job":"","cause":"","solution":"銷退單若要自動產生結帳單，請於『單據性質建立作業-COPI03』設定【直接結帳】為y.逐筆或Y.整張，並選擇【結帳單別】，之後登打銷退單存檔後即可自動流生。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:826705"]={"id":"error:826705","ty":"error","sourceId":"826705","title":"銷貨單拋轉收入分錄，拋轉後會科錯誤非分錄性質設定之科目","ver":"GP4.0.27.1以上","topic":"","job":"","cause":"","solution":"可至『品號資料建立作業』查看此品號的【會計】設為多少，再至『品號類別資料建立作業』【銷貨收入科目】查看對應的會計科目為何。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:834988"]={"id":"error:834988","ty":"error","sourceId":"834988","title":"銷貨單的單據日期能不能顯示英文的月份，日、年都顯示數字","ver":"iGP 1.0.12以上","topic":"","job":"","cause":"","solution":"目前無此功能","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:845575"]={"id":"error:845575","ty":"error","sourceId":"845575","title":"銷貨單無法取消確認出現102425","ver":"GP4.0 以上","topic":"","job":"","cause":"","solution":"1.可先至ERP首頁->『工作管理員』-> 【訊息管理】頁籤->點選【更新訊息】 2.＂訊息類別E 代號:102425不存在＂該錯誤訊息表示＂來源訂單 已指定結案,不可取消確認!＂ 3.可以先確認銷貨單的來源訂單是否是指定結案，若該訂單已被指定結案，建議客戶使用訂單變更單取消指定結案","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:817187"]={"id":"error:817187","ty":"error","sourceId":"817187","title":"銷貨單發票輸入錯誤","ver":"GP4.0.19.0以上","topic":"","job":"","cause":"","solution":"可串查至客戶資料建立作業，假設有購買EIN模組，需再基本資料(二)頁簽補入加值中心代號才可抓取不透過泛宇加值中新上傳之發票本。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:867694"]={"id":"error:867694","ty":"error","sourceId":"867694","title":"銷貨單新增時需補齊批號資料","ver":"iGP 1.0.18","topic":"","job":"","cause":"","solution":"在銷貨單新增單據時，若點選【儲存】按鈕後出現「單身料號需做批號管理，請先補齊正確批號資料」的錯誤訊息，表示該料號需要進行批號管理。解決方法為在新增銷貨單時，手動輸入或選擇正確的批號資料，確保批號管理欄位不為空。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:834900"]={"id":"error:834900","ty":"error","sourceId":"834900","title":"銷貨單臺幣金額拋轉至結帳單的臺幣金額，出現了不一致的情況","ver":"iGP1.0.13.以上","topic":"","job":"","cause":"","solution":"(1)因銷貨單單別有設定直接結帳，是設定整張，說明若金額要與銷貨單一致，建議改用逐筆結帳，此時銷貨單與結帳單單身筆數一致算法一致，即不會有差額； (2)但如果結帳單希望維持一筆總額呈現，則建議改成是\"整張資料計算\"，這樣即使銷貨單單身多筆明細，一樣會是用總原幣金額*匯率計算本幣金額， 補充：稅額計算方式若為【整張資料計算】單據無法自行調整單身本幣金額與稅額，【單身單筆計算】單據才可自行調整單身本幣金額與稅額。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:843414"]={"id":"error:843414","ty":"error","sourceId":"843414","title":"憑證的每頁頁尾都會出現簽核欄，要如何設定最終頁顯示就好","ver":"GP4.0.11.0以上","topic":"","job":"","cause":"","solution":"『單據性質設定作業』中的【每頁列印簽核】選項取消勾選，這樣憑證的簽核欄只會在最後一頁顯示。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:862837"]={"id":"error:862837","ty":"error","sourceId":"862837","title":"應付憑單 (EPMI02) 執行電子簽核時，無法正常傳送至 BPM 測試區，或簽核後未正確回寫，應檢查何處","ver":"iGP 以上","topic":"","job":"","cause":"","solution":"開啟 ERP 內之「ADMI13 電子表單佇列工作」，核對單據送簽的公司別與使用者。確保該人員在對應公司別下具備「確認」權限。 2.環境核對：確認 BPM 測試區之電子關聯表單（ADMI11）已正確建立。若使用者已自行調整權權限與路徑配置，系統即可恢復正常送簽流程。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:871356"]={"id":"error:871356","ty":"error","sourceId":"871356","title":"應付憑單列印時，簽核欄位無法帶出開單人員名稱，應如何設定","ver":"GP4.0","topic":"","job":"","cause":"簽核格式尚未正確連結至單據性質設定，因此系統無法帶入開單人員資訊。","solution":"1. 先於 CMSI17 建立簽核格式。 2. 開啟各模組的單據性質設定作業。 3. 找到「簽核代號」欄位。 4. 按 F2 選取已建立的簽核格式代號。 5. 若需每頁顯示簽核欄，請勾選「每頁列印簽核」。 6. 重新預覽或列印單據確認結果。 【其他補充】：完成簽核格式連結後，即可正常帶出開單人員資訊。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:830104"]={"id":"error:830104","ty":"error","sourceId":"830104","title":"點選【ERP Messager】出現錯誤訊息\"伺服器執行失敗, ProgID: \"ERPMessage.Class1\"","ver":"iGP 1.0.8.以上","topic":"","job":"ERP Messager","cause":"","solution":"在【工作管理員】ERPCallbackService結束工作，我的電腦【管理】→【服務】→重啟ERPCallbackService服務","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:811053"]={"id":"error:811053","ty":"error","sourceId":"811053","title":"點選自訂不可空白欄位出現:E 代號:102491不存在","ver":"iGP 1.0.14以上","topic":"","job":"","cause":"","solution":"『登入者代號建立作業』要有系統管理員的權限","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:825609"]={"id":"error:825609","ty":"error","sourceId":"825609","title":"權限設定可以依單別區分嗎","ver":"GP4.0.18.0以上","topic":"","job":"","cause":"","solution":"單別的相關權限設定，僅有『單據性質設定作業』中的【單別限定使用者】，若此單別有勾選，需另外在子單頭維護要給予新增此單別權限的帳號，若無維護於此，此帳號登打單據就無法新增此單別。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:869898"]={"id":"error:869898","ty":"error","sourceId":"869898","title":"B2C作廢發票無法印出","ver":"iGP 1.0.9.以上","topic":"","job":"","cause":"","solution":"【僅列印作廢發票】此選項只能列印B2B發票；B2C有中獎考量，因此發票作廢不能列印","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:821388"]={"id":"error:821388","ty":"error","sourceId":"821388","title":"EPMI34請購單 的專案代號 如果有做預算控管，單身的預算控管序號沒有填的話，系統會跳出錯誤訊息嗎","ver":"GP4.0.18.0以上","topic":"","job":"","cause":"","solution":"當是否控管預算=Y且品號類型=1材料，且材料控管依據=2請購或材料控管依據=1採購且領料數量不等於0時，請購單單身的預算控管序號會為必填欄位，若沒填寫會跳出錯誤訊息。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:807519"]={"id":"error:807519","ty":"error","sourceId":"807519","title":"ERP有設定要走EF電子簽核，但是目前無法送簽核，EF上沒有單據","ver":"iGP 1.0.13以上","topic":"","job":"","cause":"","solution":"ERP單據按【確認、取消確認、修改、刪除】後出現「產生工作佇列資料重複或表單正在簽核中」，請先到『電子表單佇列工作建立ADMI13』查看錯誤訊息。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:875284"]={"id":"error:875284","ty":"error","sourceId":"875284","title":"ERP簽核單據出現簽核錯誤(2130-20260620001-0001已結案)","ver":"GP4.0 以上","topic":"","job":"","cause":"","solution":"1.錯誤訊息為單據XXXX-XXXXXXXX已結案，此訊息代表來源單據已結案，請確認該單據狀態是否已結案，若已結案請確認是否已有其他單據已滿足已交量。","quoted":false,"file":"errors.jsonl"};
self.KB_CONTENT["error:828761"]={"id":"error:828761","ty":"error","sourceId":"828761","title":"KMI沒有出現想要的生產線別","ver":"iGP 1.0.10以上","topic":"","job":"","cause":"","solution":"該生產線為一般站時，KMI查看不到該生產線資料，請調整為設備追蹤站 SFT路徑為系統設定->追蹤模式設定","quoted":false,"file":"errors.jsonl"};
